package local.proskurnin.remote;
import android.content.Context;import javax.net.ssl.*;import java.security.*;import java.io.*;
final class RemoteTls {
 static SSLServerSocket server(Context c)throws Exception{File dir=c.getFilesDir();String pass=new String(read(new File(dir,"tls-password"),128),"UTF-8").trim();KeyStore keys=KeyStore.getInstance("PKCS12");try(InputStream in=new ByteArrayInputStream(read(new File(dir,"remote.p12"),16384))){keys.load(in,pass.toCharArray());}KeyManagerFactory km=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());km.init(keys,pass.toCharArray());SSLContext context=SSLContext.getInstance("TLS");context.init(km.getKeyManagers(),null,new SecureRandom());SSLServerSocket server=(SSLServerSocket)context.getServerSocketFactory().createServerSocket();server.setEnabledProtocols(new String[]{"TLSv1.2"});return server;}
 static byte[] read(File file,int limit)throws Exception{File config=new File(file.getParentFile(),"portable-config.json");if(config.exists()){org.json.JSONObject files=new org.json.JSONObject(new String(readRaw(config,65536),"UTF-8")).getJSONObject("files");if(files.has(file.getName())){byte[] data=android.util.Base64.decode(files.getString(file.getName()),android.util.Base64.DEFAULT);if(data.length>limit)throw new IOException();return data;}}return readRaw(file,limit);}
 static byte[] readRaw(File file,int limit)throws Exception{if(file.length()>limit)throw new IOException();try(InputStream in=new android.util.AtomicFile(file).openRead();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException();out.write(b,0,n);}return out.toByteArray();}}
}
